            for (uint256 j = 0; j < existingIds.length; j++) {
                if (sortedDepositIds[i] == existingIds[j]) {
                    idFound = true;
                    break;
                }
            }
            require(idFound, "ID not found in current list");
        }

        // Update the sorted list in storage
        LibSilo._setSortedDepositIds(account, token, sortedDepositIds);
