    AppStorage internal s;

    //////////////////// SEED GAUGE GETTERS ////////////////////

    /**
     * @notice Returns the average grown stalk per BDV.
     */
    function getAverageGrownStalkPerBdv() public view returns (uint256) {
        return LibSeedGauge.getAverageGrownStalkPerBdv();
