     * @dev No cap is applied to the deltaB.
     */
    function poolDeltaBNoCap(address pool) external view returns (int256) {
        if (LibWell.isWell(pool)) return LibWellMinting.checkDeltaB(pool);
        revert("Oracle: Pool not supported");
    }

    /**
