    function getTwaLiquidityForWell(address well) public view returns (uint256) {
        (address token, ) = LibWell.getNonBeanTokenAndIndexFromWell(well);
        uint256 twaLiquidity = LibWell.getTwaLiquidityFromPump(
            well,
