        for (uint256 i = 0; i < newAllocations.length; i++) {
            totalPercent += newAllocations[i].optimalPercentDepositedBdv;
        }
        require(
            totalPercent <= 100e6, // 100% in basis points
            "InitWhitelistRebalance: Total allocations exceed 100%"
        );
    }
}

