    uint256 constant BUDGET_POINTS = 3_000_000_000_000_000;
    uint256 constant PAYBACK_FIELD_POINTS = 1_000_000_000_000_000;
    uint256 constant PAYBACK_CONTRACT_POINTS = 2_000_000_000_000_000;

