    CURRENT_RESERVES,
    INSTANTANEOUS_RESERVES,
    CAPPED_RESERVES
}

contract WellPrice {
    using LibRedundantMath256 for uint256;
    using SafeCast for uint256;

    IBeanstalk immutable beanstalk;

    constructor(address _beanstalk) {
        beanstalk = IBeanstalk(_beanstalk);
