    uint256 private constant WELL_DECIMALS = 1e18;
    uint256 private constant PRICE_PRECISION = 1e6;

    struct Pool {
        address pool;
        address[2] tokens;
        uint256[2] balances;
        uint256 price;
        uint256 liquidity;
        uint256 beanLiquidity;
        uint256 nonBeanLiquidity;
        int256 deltaB;
        uint256 lpUsd;
        uint256 lpBdv;
    }

    struct SwapData {
        address well;
        address token;
        uint256 usdValue;
        uint256 amountOut;
    }

