        );

        // Update lastConvertBonusTaken
        gd.lastConvertBonusTaken = newLastConvertBonusTaken;

        // Encode and store updated gauge data
        s.sys.gaugeData.gauges[GaugeId.CONVERT_UP_BONUS].data = abi.encode(gd);
    }
}

