        vm.prank(C.PIPELINE);
        IERC20(WETH).approve(BEAN_ETH_WELL, type(uint256).max);

        vm.prank(farmers[0]);
        bs.farm{value: 1e18}(farmCalls);

        assertGt(IERC20(BEAN).balanceOf(farmers[0]), farmerInitialBeans);
    }
}

