        assertEq(field.totalUnharvestable(0), totalPodsIssued, "invalid unharvestable");
        assertEq(field.podIndex(0), totalPodsIssued, "invalid pod index");

        assertEq(field.totalSoil(), soilAvailable - totalAmountSown);
    }

