                bs.getGaugeValue(GaugeId.CONVERT_DOWN_PENALTY),
                (uint256, uint256)
            );
            console.log(
                "penalty %:",
                convertDownPenalty,
                ", rolling seasons above peg:",
                rollingSeasonsAbovePeg
            );
        }
    }

