// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;
pragma abicoder v2;

import "forge-std/Test.sol";
import "forge-std/console.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {IWell} from "contracts/interfaces/basin/IWell.sol";

import {DeltaBProbe} from "test/foundry/forks/DeltaBProbe.sol";

contract PintoDeltaBManipulationTest is Test {
    DeltaBProbe probe;
    address targetWell;

    function setUp() public {
        // Fork Base mainnet using env var BASE_RPC
        string memory baseRpc = vm.envString("BASE_RPC");
        vm.createSelectFork(baseRpc);

        probe = new DeltaBProbe();

        address[] memory wells = probe.getWhitelistedWellLpTokens();
        require(wells.length > 0, "No whitelisted wells found");
        targetWell = wells[0];

        console.log("Using well:", targetWell);
    }

    function testDeltaBDivergenceAfterSwap() public {
        int256 beforeInst = probe.overallCurrentDeltaB();
        int256 beforeCap = probe.overallCappedDeltaB();
        int256 beforeScaledInst = probe.scaledOverallCurrentDeltaB();

        console.log("beforeInst:", beforeInst);
        console.log("beforeCap:", beforeCap);
        console.log("beforeScaledInst:", beforeScaledInst);

        // Pump instantaneous reserves by performing a small swap on the target well.
        IERC20[] memory toks = IWell(targetWell).tokens();
        IERC20 fromToken = toks[0];
        IERC20 toToken = toks[1];

        uint256 amountIn = 1_000_000; // 1e6 units (suitable for 6-dec tokens; small for 18-dec)

        // Fund this test contract with the fromToken and approve the Well
        deal(address(fromToken), address(this), amountIn, true);
        fromToken.approve(targetWell, amountIn);

        // Execute swap to skew instantaneous reserves
        uint256 amountOut = IWell(targetWell).swapFrom(
            fromToken,
            toToken,
            amountIn,
            0,
            address(this),
            block.timestamp + 300
        );

        console.log("swap amountOut:", amountOut);

        // Read deltaB values after swap
        int256 afterInst = probe.overallCurrentDeltaB();
        int256 afterCap = probe.overallCappedDeltaB();
        int256 afterScaledInst = probe.scaledOverallCurrentDeltaB();

        console.log("afterInst:", afterInst);
        console.log("afterCap:", afterCap);
        console.log("afterScaledInst:", afterScaledInst);

        // The instantaneous and capped deltaB should diverge after pumping reserves.
        // This demonstrates that convert uses instantaneous (scaled) deltaB,
        // enabling manipulation between before/after snapshots.
        assertTrue(afterInst != afterCap, "Instant vs capped deltaB should differ after swap");

        // Scaled instantaneous deltaB should track the instantaneous reading trend.
        // Not asserting equality due to LP supply scaling, but it should not equal the capped reading.
        assertTrue(
            afterScaledInst != afterCap,
            "Scaled instantaneous deltaB should not equal capped deltaB"
        );
    }
}

