                WBTC_USD_CHAINLINK_PRICE_AGGREGATOR,
                bytes4(0),
                bytes1(0x01),
                abi.encode(LibChainlinkOracle.FOUR_HOUR_TIMEOUT)
            )
        );
        uint256 price = OracleFacet(BEANSTALK).getUsdTokenPrice(WBTC);
        assertEq(price, 0.00002e8, "price using encode type 0x01");

